    "code": "// 本示例从普通类型开始，逐步展示 TS++ 的 kind、高阶类型和类型宇宙。\n\n// 1. Type 是 Type0 的兼容写法。\n// number、string、数组和元组等普通 TypeScript 类型都位于 Type0。\ntype NumberAtType0: Type0 = number;\ntype StringAtType: Type = string;\n\n// 2. 普通泛型别名会从类型参数推导出自己的 kind。\n// Pair 接受两个 Type0，最后产生一个 Type0，因此它的 kind 是：\n//     (Type0, Type0) => Type0\ntype Pair<A, B> = [A, B];\n\n// 高阶类型参数可以接收 Pair 这样的“类型构造器”。\ntype Apply2<F: (Type0, Type0) => Type0, A, B> = F<A, B>;\ntype NamedAge = Apply2<Pair, string, number>;\n\nconst namedAge: NamedAge = [\"Ada\", 36];\n\n// 3. 非泛型别名若要把类型构造器保存为一等类型值，需要手动标注 kind。\n// Arrays 不是具体的数组类型；它是一个等待类型参数的类型构造器。\ntype Arrays: Type0 => Type0 = Array;\ntype StringArray = Arrays<string>;\n\n// 4. 高阶类型参数让 Functor 可以抽象于 Array、Promise 等类型构造器。\n// 当前示例为 Array 提供一个 Functor 实现。\ninterface Functor<F: Type0 => Type0> {\n    map<A, B>(fa: F<A>, fn: (value: A) => B): F<B>;\n}\n\nconst arrayFunctor: Functor<Arrays> = {\n    map: (values, fn) => values.map(fn),\n};\n\n// map 从 number[] 和 number => string 推导出 labels 为 string[]。\nconst labels = arrayFunctor.map<number, string>([1, 2, 3], value => `item-${value}`);\nconst checkedLabels: StringArray = labels;\n\nlabels.push(\"item-4\");\n\n// 5. 类型宇宙本身也有类型：Type0 : Type1、Type1 : Type2，以此类推。\n// TypeN 没有固定的最大层级；编译器按需识别任意非负整数 N。\ntype UniverseZero: Type1 = Type0;\ntype UniverseOne: Type2 = Type1;\n\n// 宇宙别名在 kind 中会透明展开，所以下面等价于 Type0 => Type0。\ntype ArraysThroughUniverseAlias: UniverseZero => UniverseZero = Array;\ntype NumberArrayThroughUniverseAlias = ArraysThroughUniverseAlias<number>;\n\n// 类型宇宙可以作为受更高宇宙约束的类型参数传递。\ntype IdentityAtOne<K: Type1>: Type1 = K;\ntype PreservedType0: Type1 = IdentityAtOne<Type0>;\n\n// 6. 当前采用非累积宇宙：Type0 与 Type1 不会自动互相提升或兼容。\n// 以下是由 @ts-expect-error 保护的反例：它们必须持续产生预期错误。\ntype LocalArray<T> = T[];\n// @ts-expect-error -- 缺少保存类型构造器所需的 kind 标注\ntype MissingConstructorKind = LocalArray;\ntype HigherKindedBox<F: Type0 => Type0> = F<string>;\n// @ts-expect-error -- string 的 kind 不是 Type0 => Type0\ntype InvalidHigherKindedBox = HigherKindedBox<string>;\n// @ts-expect-error -- Type0 本身位于 Type1\ntype InvalidUniverse: Type0 = Type0;\n// @ts-expect-error -- labels 的元素是 string\nlabels.push(4);\n\nexport { arrayFunctor, checkedLabels, labels, namedAge };\nexport type {\n    Apply2,\n    Arrays,\n    ArraysThroughUniverseAlias,\n    Functor,\n    IdentityAtOne,\n    NamedAge,\n    NumberArrayThroughUniverseAlias,\n    NumberAtType0,\n    Pair,\n    PreservedType0,\n    StringArray,\n    StringAtType,\n    UniverseOne,\n    UniverseZero,\n};\n"
