        "name": "07-recursive-data.tspp",
        "code": "data BigIntList = End | Link(head: bigint, tail: BigIntList);\n\nfunction singleton(value: bigint) with {\n  ensures: result._tag === \"Link\";\n}: BigIntList {\n  return Link(value, End);\n}\n\nfunction firstOrZero(input: BigIntList) with {\n  ensures: result === result;\n}: bigint {\n  switch (input._tag) {\n    case \"Link\":\n      return input.head;\n    case \"End\":\n      return 0n;\n  }\n}\n\nconst values = singleton(42n);\nconsole.log(`firstOrZero(singleton(42)) = ${firstOrZero(values)}`);\n"
